// OWNERS: the one table to edit if salespeople have Metrics of their own (from a Pack that makes one per salesperson,
// or duplicates of the team's Metrics). Leave the list empty to send the team's figures only.
// One line per salesperson:
//   owner     the Salesforce User id of the opportunity owner, 15 or 18 characters starting with 005
//   others    the slug of that person's Metric (the last part of the Metric's address in Ziffr). Leave one out, or
//             empty, to send nothing for it.
// Owner ids stay in n8n: Ziffr is sent only a slug, a week and a number.
const OWNERS = [
  // { owner: '005000000000001AAA', closed: 'closed-this-quarter-ana', pipeline: 'pipeline-value-ana', commit: 'commit-ana', bestCase: 'best-case-ana' },
];
return [{ json: { owners: OWNERS } }];

// Which week, and which quarter (the CRM forecast templates share this node). The figures are for the week that ended
// last (Monday to Sunday, as Ziffr counts weeks) in the time zone of the Settings node. The quarter is the one that
// week starts in, counted from the month your Workspace's year starts in, which Ziffr says ("What is filled").
//  - Pipeline, commit and best case are what the CRM says at the moment of the run, so they are sent only when the run is
//    on Monday or Tuesday: a later run never files today's pipeline under last week. Closed this quarter is read by the
//    close date, so it can be sent on any day.
//  - A week Ziffr still counts as running (it counts days on its own server, normally in UTC) is not sent: it would not
//    count as past, and a second run could then replace it.
const DAY = 86400000;
const s = $('Settings').first().json;
const zone = String(s.timeZone ?? '').trim();
let clock;
try {
  if (zone === '') throw new Error('empty');
  clock = new Intl.DateTimeFormat('en-US', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' });
} catch {
  throw new Error('Settings: timeZone is not a time zone. Write it like Europe/Berlin, America/New_York or UTC.');
}
// The time of day a clock in that zone shows at an instant, written as if it were UTC.
const wall = (at) => {
  const p = Object.fromEntries(clock.formatToParts(new Date(at)).map((x) => [x.type, Number(x.value)]));
  return Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute, p.second);
};
// The instant a day begins in that zone (asked twice, since the clocks may change in between).
const startOfDay = (day) => {
  const guess = day - (wall(day) - day);
  return day - (wall(guess) - guess);
};
const iso = (day) => new Date(day).toISOString().slice(0, 10);

const today = Math.floor(wall(Date.now()) / DAY) * DAY;
const sinceMonday = (new Date(today).getUTCDay() + 6) % 7;
const weekFirst = today - (sinceMonday + 7) * DAY;
const period = iso(weekFirst);

const overview = $('What is filled').first().json;
const yearStart = overview.year_start_month;
if (!Number.isInteger(yearStart) || yearStart < 1 || yearStart > 12) throw new Error('Ziffr did not say which month your year starts in; check the Ziffr address and the Feed Key. No figure was sent.');
const first = new Date(weekFirst);
const into = (first.getUTCMonth() - (yearStart - 1) + 12) % 12;
const quarterFirst = Date.UTC(first.getUTCFullYear(), first.getUTCMonth() - (into % 3), 1);
const next = new Date(quarterFirst);
const quarterEnd = Date.UTC(next.getUTCFullYear(), next.getUTCMonth() + 3, 1);
// Deals won count up to the end of the week, but never past the quarter the week belongs to.
const wonLast = Math.min(weekFirst + 6 * DAY, quarterEnd - DAY);

// Every Metric named here must be weekly, and the week must be over for Ziffr too.
const named = new Set(['closedMetric', 'pipelineMetric', 'commitMetric', 'bestCaseMetric'].map((k) => String(s[k] ?? '').trim()));
for (const line of [].concat($('Owners').first().json.owners ?? [])) for (const v of Object.values(line ?? {})) named.add(String(v).trim());
const listed = overview.metrics && Array.isArray(overview.metrics.items) ? overview.metrics.items : [];
for (const m of listed.filter((x) => named.has(x.slug))) {
  if (m.period !== 'week') throw new Error('The Metric ' + m.slug + ' is not weekly. These figures are weekly: use weekly Metrics. No figure was sent.');
  if (typeof m.current === 'string' && m.current <= period) throw new Error('Ziffr still counts the week of ' + period + ' as running (it counts days in its server\'s time, normally UTC). Run this later on Monday, after 00:00 UTC. No figure was sent.');
}
// The Salesforce login is sent to this address, so only a Salesforce one is taken.
if (!/^https:\/\/[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.salesforce\.com\/?$/.test(String(s.instanceUrl ?? '').trim())) throw new Error('Settings: instanceUrl is your Salesforce address, such as https://yourcompany.my.salesforce.com.');

return [{ json: {
  period,
  quarterFirst: iso(quarterFirst),
  quarterLast: iso(quarterEnd - DAY),
  wonLast: iso(wonLast),
  // The same bounds as instants, for a CRM that keeps dates with a time of day.
  fromMs: startOfDay(quarterFirst),
  wonBeforeMs: startOfDay(wonLast + DAY),
  beforeMs: startOfDay(quarterEnd),
  changedSince: new Date(startOfDay(quarterFirst) - DAY).toISOString().slice(0, 19) + 'Z',
  snapshot: sinceMonday <= 1,
} }];

// Salesforce -> Ziffr: the week's sales forecast figures. The first part of this node reads what Salesforce answered and makes
// one plain line { owner, kind, amount, category } per deal that counts: kind is 'won' (this quarter, up to the week's end)
// or 'open' (can still close this quarter), category '' , 'commit' or 'upside'. The next node gets the rows
// { metric, period, value } and notes for the person running it, which may name owner ids and stay in n8n. Only the rows
// are sent to Ziffr: no deal, name, email or owner id leaves n8n.
// What is sent:
//  - closed: the amounts won;  pipeline: the amounts open (those in the commit too, those won not);
//  - commit: closed plus the open amounts in the forecast category Commit;  bestCase: closed plus the open amounts in
//    Commit, Best case and Most likely;
//  - the team's figures add up every owner; a line in Owners adds up that owner's deals only;
//  - 0 is sent when the CRM showed deals and the figure's own deals add up to nothing. When it showed no deal at all
//    (for the team, or for an owner of the table), nothing is sent: that is more often a missing right or a wrong id
//    than a real nothing, and a missing value can be typed in, while a wrong 0 would stay.
const week = $('Week').first().json;
const lines = [];
const notes = [];
// Salesforce: sums it works out itself (SUM ... GROUP BY), so no opportunity is read, only totals per owner and forecast
// category. In an org with several currencies Salesforce gives these totals in the org's default currency.
// An owner id may be pasted with 15 or 18 characters; the first 15 say who it is.
const ownerKey = (id) => String(id).slice(0, 15);
const KNOWN = ['Omitted', 'Pipeline', 'BestCase', 'MostLikely', 'Forecast', 'Closed'];
const totalsOf = (node) => {
  const answer = $(node).first().json;
  if (!Array.isArray(answer.records)) throw new Error('Salesforce did not answer with totals (' + node + '). No figure was sent.');
  // A grouped query hands out at most 2,000 rows and no further page.
  if (answer.done !== true || answer.records.length >= 2000) throw new Error('Salesforce has more groups than one query hands out (' + node + '). No figure was sent.');
  return answer.records;
};
let unpriced = 0;
const take = (node, kind) => {
  for (const r of totalsOf(node)) {
    const amount = r.amountSum === null || r.amountSum === undefined ? 0 : Number(r.amountSum);
    if (!Number.isFinite(amount)) throw new Error('Salesforce gave a total that is not a number. No figure was sent.');
    unpriced += Math.max(0, Number(r.dealCount || 0) - Number(r.pricedCount || 0));
    const c = r.ForecastCategory;
    if (kind === 'open' && c !== null && c !== undefined && !KNOWN.includes(c)) throw new Error('Salesforce named a forecast category this template does not know: ' + String(c).slice(0, 40) + '. No figure was sent.');
    const category = kind !== 'open' ? '' : c === 'Forecast' ? 'commit' : c === 'BestCase' || c === 'MostLikely' ? 'upside' : '';
    lines.push({ owner: String(r.OwnerId ?? ''), kind, amount, category });
  }
};
take('Read won totals', 'won');
take('Read open totals', 'open');
if (unpriced) notes.push({ why: unpriced + ' opportunity(ies) have no amount and count as 0' });

// ---- the same for every CRM from here on ----
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const OWNER = /^[A-Za-z0-9]{1,40}$/;
const FIGURES = ['closed', 'pipeline', 'commit', 'bestCase'];
const s = $('Settings').first().json;
const slugIn = (value, where, optional) => {
  const v = String(value ?? '').trim();
  // The commit and best case settings are optional: left as they came, they send nothing.
  if (v === '' || (optional && v.startsWith('REPLACE-WITH-'))) return '';
  if (!SLUG.test(v)) throw new Error(where + ' is not a Metric slug (lower case letters, digits and hyphens), or leave it empty to skip that figure.');
  return v;
};
const used = new Set();
const once = (slug) => {
  if (!slug) return slug;
  if (used.has(slug)) throw new Error('The Metric ' + slug + ' is named twice (Settings or Owners); each figure needs its own. No figure was sent.');
  used.add(slug);
  return slug;
};
const team = {};
for (const f of FIGURES) team[f] = once(slugIn(s[f + 'Metric'], 'Settings: ' + f + 'Metric', f === 'commit' || f === 'bestCase'));

const table = $('Owners').first().json.owners;
if (!Array.isArray(table)) throw new Error('Owners: OWNERS is not a list.');
const seenOwners = new Set();
const people = table.map((line, i) => {
  const where = 'Owners, line ' + (i + 1);
  const owner = String(line?.owner ?? '').trim();
  if (!OWNER.test(owner)) throw new Error(where + ': owner is not an owner id (letters and digits only, as the CRM shows it).');
  const extra = Object.keys(line).filter((k) => k !== 'owner' && !FIGURES.includes(k));
  if (extra.length) throw new Error(where + ': “' + extra[0].slice(0, 40) + '” is not known; a line takes owner, ' + FIGURES.join(', ') + '.');
  if (seenOwners.has(ownerKey(owner))) throw new Error(where + ': the same owner appears twice.');
  seenOwners.add(ownerKey(owner));
  const slugs = {};
  for (const f of FIGURES) slugs[f] = once(slugIn(line[f], where + ': ' + f, false));
  return { owner, slugs };
});
if (used.size === 0) throw new Error('Name at least one Metric to fill, in the Settings node or in Owners.');

const sum = (list) => list.reduce((total, l) => total + l.amount, 0);
const figuresOf = (list) => {
  const won = sum(list.filter((l) => l.kind === 'won'));
  const open = list.filter((l) => l.kind === 'open');
  return {
    closed: won,
    pipeline: sum(open),
    commit: won + sum(open.filter((l) => l.category === 'commit')),
    bestCase: won + sum(open.filter((l) => l.category !== '')),
  };
};
const rows = [];
let late = false;
const add = (slugs, list, nobody) => {
  if (!Object.values(slugs).some(Boolean)) return;
  if (list.length === 0) { notes.push({ why: nobody }); return; }
  const values = figuresOf(list);
  for (const f of FIGURES) {
    if (!slugs[f]) continue;
    if (f !== 'closed' && !week.snapshot) { late = true; continue; }
    rows.push({ metric: slugs[f], period: week.period, value: Math.round(values[f] * 100) / 100 });
  }
};
add(team, lines, 'Salesforce showed no deal at all for this quarter: nothing is sent for the team (not 0). Check that the login may see the deals.');
for (const p of people) add(p.slugs, lines.filter((l) => ownerKey(l.owner) === ownerKey(p.owner)), 'Salesforce showed no deal of owner ' + p.owner + ' for this quarter: nothing is sent for them (not 0). Check the id.');
if (late) notes.push({ why: 'Pipeline, commit and best case are what the CRM says today, so they are sent only on a Monday or Tuesday. Only closed this quarter was sent for the week of ' + week.period + '.' });
// Ids only, to help fill the table: whose deals are in this read and have no line.
const unlisted = [...new Set(lines.map((l) => l.owner).filter((o) => o !== '' && !seenOwners.has(ownerKey(o))))].filter((o) => OWNER.test(o));
if (unlisted.length) notes.push({ why: 'Owner ids with deals and no line in Owners (they count towards the team only): ' + unlisted.slice(0, 50).join(', ') + (unlisted.length > 50 ? ' and more' : '') });
return [{ json: { rows, skipped: notes, none: 'Nothing was sent for the week of ' + week.period + '. ' + notes.map((n) => n.why).join(' ') } }];

// Shape values (spec 0043): the one node every Feed template shares. The source node before it hands over plain rows
// { metric, value, period?, row? } and nothing else; this node is what makes them safe to send, whatever the source is:
//  - each row is checked as Ziffr would check it (a Metric slug, a plain number, a period written as a day), a row that fails is
//    skipped and said so, the same Metric and period twice is skipped, and at most 500 are sent;
//  - Ziffr is asked which periods already hold a value (the node "What is filled", GET /api/v1/feed, as @ziffr/feed-kit does) and a
//    past period that has one is not sent again, so a rerun, a manual run or a later run never overwrites, adds to or doubles what
//    is there, whatever the Metric's Submission Rule; the current period is always sent, since its value may still change;
//  - the key is made from the figures alone, so a retried run records nothing twice.
// Only { metric, period, value } leaves: no other field of a row is read.
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;
const NUMBER = /^-?\d+(\.\d+)?$/;
const MAX_ITEMS = 500;
const given = $input.first().json;
const rows = Array.isArray(given.rows) ? given.rows : [];
const skipped = Array.isArray(given.skipped) ? [...given.skipped] : [];
const items = [];
const seen = new Set();
rows.forEach((r, n) => {
  const row = r.row ?? n + 1;
  const metric = String(r.metric ?? '').trim();
  const raw = typeof r.value === 'number' ? String(r.value) : String(r.value ?? '').trim();
  const period = String(r.period ?? '').trim();
  if (metric === '' && raw === '' && period === '') return;
  if (!SLUG.test(metric)) { skipped.push({ row, why: 'the metric is not a Metric slug' }); return; }
  if (!NUMBER.test(raw)) { skipped.push({ row, metric, why: 'the value is not a plain number' }); return; }
  if (period !== '' && !DAY.test(period)) { skipped.push({ row, metric, why: 'the period is not a day written YYYY-MM-DD' }); return; }
  const at = metric + '/' + period;
  if (seen.has(at)) { skipped.push({ row, metric, why: 'the same Metric and period appear twice' }); return; }
  seen.add(at);
  if (items.length >= MAX_ITEMS) { skipped.push({ row, metric, why: 'more than ' + MAX_ITEMS + ' rows' }); return; }
  items.push(period === '' ? { metric, value: Number(raw) } : { metric, period, value: Number(raw) });
});
if (items.length === 0) throw new Error(String(given.none || 'No figure to send: nothing holds a Metric slug and a number.'));

const overview = $('What is filled').first().json;
const listed = overview && overview.metrics && Array.isArray(overview.metrics.items) ? overview.metrics.items : [];
if (overview && overview.metrics && overview.metrics.next) throw new Error('This Feed submits to more than 100 Metrics; this template reads that many at most (use a second Feed for the rest). No figure was sent.');
const metricOf = new Map(listed.map((m) => [m.slug, m]));
const send = items.filter((i) => {
  const m = metricOf.get(i.metric);
  return !(m && i.period && i.period !== m.current && Array.isArray(m.filled) && m.filled.includes(i.period));
});
const settled = items.length - send.length;
if (send.length === 0) return [];

let h = 5381;
const body = JSON.stringify(send);
for (let i = 0; i < body.length; i++) h = ((h * 33) ^ body.charCodeAt(i)) >>> 0;
const key = 'salesforce-forecast-' + h.toString(36) + '-' + send.length;
return [{ json: { items: send, skipped, settled, key } }];

// Ziffr's answer to a batch of values (spec 0043): one result per item, in the order sent. A refused item fails the run,
// so that n8n shows it as failed and its owner looks; the rest were recorded all the same (each item stands on its own).
const results = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const shaped = $('Shape values').first().json;
const refused = results.filter((r) => r.status === 'refused');
if (refused.length) {
  const why = refused.slice(0, 10).map((r) => String(r.metric) + ' ' + String(r.period ?? '') + ' (' + String(r.code ?? 'refused') + '): ' + String(r.detail)).join('; ');
  throw new Error('Ziffr refused ' + refused.length + ' of ' + results.length + ' values: ' + why + (refused.length > 10 ? '; and more' : ''));
}
const count = (s) => results.filter((r) => r.status === s).length;
return [{ json: { recorded: count('recorded'), waitingForApproval: count('awaiting_approval'), proposedAsCorrection: count('locked'), alreadyThere: shaped.settled, skippedRows: shaped.skipped } }];
